    return ("tied", set().union(*(subhits(eb, files, paths[p], cap(p)) for p in top)))

def stage(root, files, f, spec):
    cov = covering(root, f)
    if cov is None: return ("fail-closed", None)
    if len(cov) != 1: return ("no-sole-project", len(cov))
    if cov[0] is None: return ("no-paths", None)
    k, h = hits(cov[0], files, spec)
    if k == "none": return ("no-match", None)
    if not h: return ("no-hit" if k == "selected" else "tie-no-hit", None)
    if k == "tied": return ("tied", h)
    return ("static", h) if len(h) == 1 else ("ambiguous", h)

